INSERT INTO public.knowledge_base (content, metadata, embedding, user_id) VALUES ('w dziedzinie bezpieczeństwa i higieny użytkowania sprzętu roboczego przez pracowników 
podczas pracy (druga dyrektywa szczegółowa w rozumieniu art. 16 ust. 1 dyrektywy 
89/391/EWG) (Dz. Urz. WE L 393 z 30.12.1989, z późn. zm.), 
6) dyrektywy 89/656/EWG z dnia 30 listopada 1989 r. w sprawie minimalnych wymagań 
w dziedzinie bezpieczeństwa i ochrony zdrowia pracowników korzystających z wyposażenia 
ochrony osobistej (trzecia dyrektywa szczegółowa w rozumieniu art. 16 ust. 1 dyrektywy 
89/391/EWG) (Dz. Urz. WE L 393 z 30.12.1989), 
7) dyrektywy 90/269/EWG z dnia 29 maja 1990 r. w sprawie minimalnych wymagań 
dotyczących ochrony zdrowia i bezpieczeństwa podczas ręcznego przemieszczania ciężarów 
w przypadku możliwości wystąpienia zagrożenia, zwłaszcza urazów kręgosłupa pracowników 
(czwarta szczegółowa dyrektywa w rozumieniu art. 16 ust. 1 dyrektywy 89/391/EWG) 
(Dz. Urz. WE L 156 z 21.06.1990), 
8) dyrektywy 90/270/EWG z dnia 29 maja 1990 r. w sprawie minimalnych wymagań 
w dziedzinie bezpieczeństwa i ochrony zdrowia przy pracy z urządzeniami wyposażonymi 
w monitory ekranowe (piąta dyrektywa szczegółowa w rozumieniu art. 16 ust. 1 dyrektywy 
89/391/EWG) (Dz. Urz. WE L 156 z 21.06.1990), 
9) dyrektywy 90/394/EWG z dnia 28 czerwca 1990 r. w sprawie ochrony pracowników przed 
